import type { Visibility } from "../lib/scans";

const OPTIONS: { value: Visibility; label: string; detail: string }[] = [
  { value: "public", label: "Public", detail: "Anyone can find it in Explore and open it." },
  { value: "unlisted", label: "Unlisted", detail: "Only people with the link or QR code can open it." },
  { value: "private", label: "Private", detail: "Only you and the people you add can open it." },
];

export function visibilityLabel(value: Visibility): string {
  return OPTIONS.find((o) => o.value === value)?.label ?? value;
}

/** Three radio cards. Real radio inputs, so keyboard arrows and screen readers work. */
export default function VisibilityPicker({
  name,
  value,
  onChange,
  disabled,
}: {
  name: string;
  value: Visibility;
  onChange: (value: Visibility) => void;
  disabled?: boolean;
}) {
  return (
    <div className="grid gap-2">
      {OPTIONS.map((option) => {
        const checked = option.value === value;
        return (
          <label
            key={option.value}
            className={`flex min-h-14 cursor-pointer items-start gap-3 rounded-xl border-2 px-4 py-3 transition-colors has-[:focus-visible]:outline-3 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-coral ${
              checked ? "border-forest bg-forest/8" : "border-forest/15 bg-surface hover:border-forest/40"
            } ${disabled ? "cursor-not-allowed opacity-60" : ""}`}
          >
            <input
              type="radio"
              name={name}
              value={option.value}
              checked={checked}
              disabled={disabled}
              onChange={() => onChange(option.value)}
              className="mt-1 size-5 shrink-0 accent-forest focus-visible:outline-none"
            />
            <span>
              <span className="block font-bold">{option.label}</span>
              <span className="block text-sm text-muted">{option.detail}</span>
            </span>
          </label>
        );
      })}
    </div>
  );
}

import { QRCodeSVG } from "qrcode.react";
import { useEffect, useRef, useState } from "react";
import { parseViewerIds, shareUrl, updateSharing, UploadError, type Visibility } from "../lib/scans";
import VisibilityPicker, { visibilityLabel } from "./VisibilityPicker";

const FOREST = "#2F4A3A";
const SURFACE = "#FAF5E6";

function isLocalHost(): boolean {
  return ["localhost", "127.0.0.1", "[::1]"].includes(window.location.hostname);
}

export default function SharePanel({
  shareId,
  sharePath,
  initialVisibility,
  initialViewerIds,
  onUploadAnother,
}: {
  shareId: string;
  sharePath: string;
  initialVisibility: Visibility;
  initialViewerIds: string[];
  onUploadAnother: () => void;
}) {
  const url = shareUrl(sharePath);
  const [saved, setSaved] = useState({ visibility: initialVisibility, viewerIds: initialViewerIds });
  const [visibility, setVisibility] = useState<Visibility>(initialVisibility);
  const [viewerText, setViewerText] = useState(initialViewerIds.join(", "));
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ tone: "ok" | "error"; text: string } | null>(null);
  const [copied, setCopied] = useState(false);
  const urlRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(timer);
  }, [copied]);

  const viewers = parseViewerIds(viewerText);
  const pendingViewers = visibility === "private" ? viewers.ids : [];
  const dirty =
    visibility !== saved.visibility || pendingViewers.slice().sort().join() !== saved.viewerIds.slice().sort().join();

  async function copy() {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
    } catch {
      // Clipboard API blocked (e.g. insecure origin): select the text so a long-press copy works.
      urlRef.current?.select();
      setMessage({ tone: "error", text: "Couldn't copy automatically. The link is selected, so copy it from there." });
    }
  }

  async function save() {
    if (viewers.invalid.length && visibility === "private") {
      setMessage({ tone: "error", text: `These aren't valid account IDs: ${viewers.invalid.join(", ")}` });
      return;
    }
    setSaving(true);
    setMessage(null);
    try {
      const result = await updateSharing(shareId, visibility, pendingViewers);
      setSaved({ visibility: result.visibility, viewerIds: result.viewerIds });
      const who =
        result.visibility === "private"
          ? result.viewerIds.length
            ? ` You and ${result.viewerIds.join(", ")} can open it.`
            : " Only you can open it."
          : "";
      setMessage({ tone: "ok", text: `Saved. This scan is now ${visibilityLabel(result.visibility)}.${who}` });
    } catch (error) {
      setMessage({ tone: "error", text: error instanceof UploadError ? error.message : "Couldn't save that change." });
    } finally {
      setSaving(false);
    }
  }

  return (
    <section aria-labelledby="share-title" className="grid gap-6">
      <div className="rounded-2xl bg-surface p-5 shadow-sm ring-1 ring-forest/10">
        <h2 id="share-title" className="font-display text-2xl font-black">
          Your link is ready
        </h2>
        <p className="mt-1 text-muted">
          Currently <strong className="text-forest">{visibilityLabel(saved.visibility)}</strong>. Guests open it signed
          out on their phone.
        </p>

        <label htmlFor="share-url" className="sr-only">
          Guest link
        </label>
        <input
          id="share-url"
          ref={urlRef}
          readOnly
          value={url}
          onFocus={(e) => e.currentTarget.select()}
          className="mt-4 w-full truncate rounded-lg bg-paper px-3 py-3 font-mono text-sm text-forest ring-1 ring-forest/15"
        />
        <div className="mt-3 grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={copy}
            className="min-h-12 rounded-full bg-forest px-4 font-bold text-paper active:scale-[0.98]"
          >
            {copied ? "Copied!" : "Copy link"}
          </button>
          <a
            href={sharePath}
            target="_blank"
            rel="noreferrer"
            className="grid min-h-12 place-items-center rounded-full px-4 font-bold text-forest ring-2 ring-forest"
          >
            Open guest view
          </a>
        </div>
        <span aria-live="polite" className="sr-only">
          {copied ? "Link copied" : ""}
        </span>

        <figure className="mt-6 flex flex-col items-center gap-3">
          <div className="rounded-xl bg-surface p-3 ring-1 ring-forest/15">
            <QRCodeSVG
              value={url}
              size={200}
              fgColor={FOREST}
              bgColor={SURFACE}
              level="M"
              marginSize={2}
              title={`QR code for ${url}`}
            />
          </div>
          <figcaption className="text-center text-sm text-muted">
            Point a phone camera here to open the guest view.
          </figcaption>
        </figure>
        {isLocalHost() ? (
          <p className="mt-3 rounded-lg bg-paper px-3 py-2 text-sm text-rust">
            This link points at <span className="font-mono">{window.location.host}</span>, which only works on this
            computer. A phone needs the deployed site.
          </p>
        ) : null}
      </div>

      <fieldset className="grid gap-3">
        <legend className="mb-2 font-display text-xl font-extrabold">Change who can open it</legend>
        <VisibilityPicker name="share-visibility" value={visibility} onChange={setVisibility} disabled={saving} />
        {visibility === "private" ? (
          <label className="grid gap-1">
            <span className="font-bold">People who can view</span>
            <span className="text-sm text-muted">Account IDs, separated by commas. Leave empty for just you.</span>
            <input
              value={viewerText}
              onChange={(e) => setViewerText(e.target.value)}
              placeholder="sam, anish"
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
              className="min-h-12 rounded-lg bg-surface px-3 font-mono ring-1 ring-forest/25 focus:ring-2 focus:ring-forest focus:outline-none"
            />
          </label>
        ) : null}
        <button
          type="button"
          onClick={save}
          disabled={!dirty || saving}
          className="min-h-12 rounded-full bg-forest px-6 font-bold text-paper disabled:bg-forest/30 disabled:text-forest/70"
        >
          {saving ? "Saving…" : "Save sharing"}
        </button>
        {message ? (
          <p role={message.tone === "error" ? "alert" : "status"} className={message.tone === "error" ? "text-rust" : ""}>
            {message.text}
          </p>
        ) : null}
      </fieldset>

      <button type="button" onClick={onUploadAnother} className="justify-self-start font-bold text-rust underline underline-offset-4">
        Upload another scan
      </button>
    </section>
  );
}

import { useEffect, useId, useRef, useState, type DragEvent } from "react";
import { Link } from "react-router";
import SharePanel from "../components/SharePanel";
import VisibilityPicker from "../components/VisibilityPicker";
import {
  checkFile,
  formatBytes,
  parseViewerIds,
  updateSharing,
  uploadScan,
  UploadError,
  type ScanFormat,
  type UploadResult,
  type Visibility,
} from "../lib/scans";

type Phase =
  | { step: "choose" }
  | { step: "uploading"; progress: number }
  | { step: "done"; result: UploadResult; visibility: Visibility; viewerIds: string[]; warning?: string };

export default function Upload() {
  const inputId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const abortRef = useRef<AbortController | null>(null);
  const [file, setFile] = useState<{ file: File; format: ScanFormat } | null>(null);
  const [fileProblem, setFileProblem] = useState<string | null>(null);
  const [visibility, setVisibility] = useState<Visibility>("unlisted");
  const [viewerText, setViewerText] = useState("");
  const [phase, setPhase] = useState<Phase>({ step: "choose" });
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);

  useEffect(() => {
    document.title = "Share a scan · Path";
    return () => abortRef.current?.abort();
  }, []);

  async function choose(chosen: File | undefined) {
    setUploadError(null);
    if (!chosen) return;
    const check = await checkFile(chosen);
    if ("problem" in check) {
      setFile(null);
      setFileProblem(check.problem);
    } else {
      setFile({ file: chosen, format: check.format });
      setFileProblem(null);
    }
  }

  function onDrop(event: DragEvent<HTMLLabelElement>) {
    event.preventDefault();
    setDragging(false);
    void choose(event.dataTransfer.files[0]);
  }

  const viewers = parseViewerIds(viewerText);

  async function upload() {
    if (!file) return;
    if (visibility === "private" && viewers.invalid.length) {
      setUploadError(`These aren't valid account IDs: ${viewers.invalid.join(", ")}`);
      return;
    }
    const controller = new AbortController();
    abortRef.current = controller;
    setUploadError(null);
    setPhase({ step: "uploading", progress: 0 });
    try {
      const result = await uploadScan({
        file: file.file,
        format: file.format,
        visibility,
        signal: controller.signal,
        onProgress: (progress) => setPhase({ step: "uploading", progress }),
      });
      let viewerIds: string[] = [];
      let warning: string | undefined;
      if (visibility === "private" && viewers.ids.length) {
        try {
          viewerIds = (await updateSharing(result.shareId, "private", viewers.ids)).viewerIds;
        } catch (error) {
          warning = `Uploaded, but adding viewers failed: ${(error as Error).message} Try again below.`;
        }
      }
      setPhase({ step: "done", result, visibility, viewerIds, warning });
    } catch (error) {
      if (controller.signal.aborted) {
        setPhase({ step: "choose" });
        return;
      }
      setPhase({ step: "choose" });
      setUploadError(error instanceof UploadError ? error.message : "The upload failed. Try again.");
    } finally {
      abortRef.current = null;
    }
  }

  function reset() {
    setFile(null);
    setFileProblem(null);
    setViewerText("");
    setUploadError(null);
    setPhase({ step: "choose" });
    if (inputRef.current) inputRef.current.value = "";
  }

  const uploading = phase.step === "uploading";

  return (
    <main className="mx-auto min-h-dvh max-w-lg px-4 pt-[max(1.25rem,env(safe-area-inset-top))] pb-16">
      <header className="flex items-center justify-between">
        <Link to="/" className="font-display text-2xl font-black tracking-wide">
          Path
        </Link>
        <span className="font-mono text-xs text-muted">organizer</span>
      </header>

      <h1 className="mt-8 font-display text-4xl leading-none font-black">Share a scan</h1>
      <p className="mt-3 text-lg text-muted">Upload your venue scan, choose who can open it, then share the link or QR code.</p>

      {phase.step === "done" ? (
        <div className="mt-8">
          {phase.warning ? (
            <p role="alert" className="mb-4 rounded-lg bg-surface px-4 py-3 text-rust ring-1 ring-rust/30">
              {phase.warning}
            </p>
          ) : null}
          <SharePanel
            shareId={phase.result.shareId}
            sharePath={phase.result.sharePath}
            initialVisibility={phase.visibility}
            initialViewerIds={phase.viewerIds}
            onUploadAnother={reset}
          />
        </div>
      ) : (
        <form
          className="mt-8 grid gap-8"
          onSubmit={(e) => {
            e.preventDefault();
            void upload();
          }}
        >
          <section className="grid gap-3">
            <h2 className="font-display text-xl font-extrabold">
              <span className="text-rust">1</span> Choose your scan
            </h2>
            <label
              htmlFor={inputId}
              onDragOver={(e) => {
                e.preventDefault();
                setDragging(true);
              }}
              onDragLeave={() => setDragging(false)}
              onDrop={onDrop}
              className={`flex min-h-36 cursor-pointer flex-col items-center justify-center gap-2 rounded-2xl border-2 border-dashed px-4 py-6 text-center transition-colors has-[:focus-visible]:outline-3 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-coral ${
                dragging ? "border-forest bg-forest/8" : "border-forest/35 bg-surface"
              } ${uploading ? "pointer-events-none opacity-60" : ""}`}
            >
              <input
                id={inputId}
                ref={inputRef}
                type="file"
                accept=".ply,.glb,application/octet-stream,model/gltf-binary"
                className="sr-only"
                disabled={uploading}
                onChange={(e) => void choose(e.target.files?.[0])}
              />
              {file ? (
                <>
                  <span className="max-w-full truncate font-mono text-forest">{file.file.name}</span>
                  <span className="text-sm text-muted">
                    {file.format.toUpperCase()} · {formatBytes(file.file.size)} · tap to change
                  </span>
                </>
              ) : (
                <>
                  <span className="font-bold">Tap to choose a file</span>
                  <span className="text-sm text-muted">PLY point cloud or GLB model, up to 32 MB</span>
                </>
              )}
            </label>
            {fileProblem ? (
              <p role="alert" className="text-rust">
                {fileProblem}
              </p>
            ) : null}
          </section>

          <fieldset className="grid gap-3" disabled={uploading}>
            <legend className="mb-3 font-display text-xl font-extrabold">
              <span className="text-rust">2</span> Who can open it
            </legend>
            <VisibilityPicker name="upload-visibility" value={visibility} onChange={setVisibility} disabled={uploading} />
            {visibility === "private" ? (
              <label className="grid gap-1">
                <span className="font-bold">People who can view</span>
                <span className="text-sm text-muted">Account IDs, separated by commas. Leave empty for just you.</span>
                <input
                  value={viewerText}
                  onChange={(e) => setViewerText(e.target.value)}
                  placeholder="sam, anish"
                  autoCapitalize="none"
                  autoCorrect="off"
                  spellCheck={false}
                  className="min-h-12 rounded-lg bg-surface px-3 font-mono ring-1 ring-forest/25 focus:ring-2 focus:ring-forest focus:outline-none"
                />
              </label>
            ) : null}
          </fieldset>

          <div className="grid gap-3">
            {uploading ? (
              <div className="grid gap-2" role="status" aria-live="polite">
                <div className="flex justify-between text-sm">
                  <span className="font-bold">Uploading…</span>
                  <span className="font-mono">{Math.round(phase.progress * 100)}%</span>
                </div>
                <div
                  className="h-3 overflow-hidden rounded-full bg-forest/15"
                  role="progressbar"
                  aria-label="Upload progress"
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-valuenow={Math.round(phase.progress * 100)}
                >
                  <div className="h-full rounded-full bg-coral transition-[width]" style={{ width: `${phase.progress * 100}%` }} />
                </div>
                <button
                  type="button"
                  onClick={() => abortRef.current?.abort()}
                  className="justify-self-start font-bold text-rust underline underline-offset-4"
                >
                  Cancel upload
                </button>
              </div>
            ) : (
              <button
                type="submit"
                disabled={!file}
                className="min-h-14 rounded-full bg-coral px-6 text-lg font-bold text-ink active:scale-[0.98] disabled:bg-forest/15 disabled:text-forest/60"
              >
                Upload and get link
              </button>
            )}
            {uploadError ? (
              <p role="alert" className="rounded-lg bg-surface px-4 py-3 text-rust ring-1 ring-rust/30">
                {uploadError}
              </p>
            ) : null}
          </div>
        </form>
      )}
    </main>
  );
}

